import{_ as t,o as r,c as i,a2 as s}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"The TUI service surface","description":"","frontmatter":{},"headers":[],"relativePath":"l1/tui-ext.md","filePath":"l1/tui-ext.md"}'),o={name:"l1/tui-ext.md"};function d(a,e,c,n,u,h){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="the-tui-service-surface" tabindex="-1">The TUI service surface <a class="header-anchor" href="#the-tui-service-surface" aria-label="Permalink to &quot;The TUI service surface&quot;">​</a></h1><p>The desktop lives in the TUI service (<code>ocos/services/tui/</code>) and reaches ring 3 through the L1SVC &quot;tui&quot; category (op family 1-9: <code>tui</code>, <code>tui-test</code>, <code>tui-hw</code>, <code>tui-net</code>, <code>tui-sysinfo</code>, <code>tui-time</code>, <code>tui-drv</code>, <code>tui-sys</code>, <code>tui-ext</code>).</p><h2 id="the-extension-registries-svc-tui-api-h" tabindex="-1">The extension registries (svc_tui_api.h) <a class="header-anchor" href="#the-extension-registries-svc-tui-api-h" aria-label="Permalink to &quot;The extension registries (svc_tui_api.h)&quot;">​</a></h2><p>All tables are static (freestanding, no malloc dependency); registration returns 0 on success, -1 table full, -2 duplicate name/key. Every entry carries its owner (&quot;builtin-...&quot; for the in-tree pages) so unregister works and re-registration is idempotent.</p><table tabindex="0"><thead><tr><th>Registry</th><th>API</th><th>What it adds</th></tr></thead><tbody><tr><td>menu</td><td><code>tui_menu_register/unregister/list/sort</code></td><td>a launcher entry: label, desc, ASCII icon, group, hotkey, priority, action callback</td></tr><tr><td>page</td><td><code>tui_page_register/unregister/list/render/input</code></td><td>a full page: render(win, scroll) + input(key) -&gt; 1 consumed; <code>tui_ext_page_main</code> is the generic runner</td></tr><tr><td>widget</td><td><code>tui_widget_register/unregister/list/render/event</code></td><td>a reusable widget type</td></tr><tr><td>command</td><td><code>tui_cmd_register/unregister/list/execute</code></td><td>a TUI command-line hook</td></tr><tr><td>theme</td><td><code>tui_theme_register/unregister/list/set</code></td><td>colour themes</td></tr><tr><td>hotkey</td><td><code>tui_key_register/unregister/list/conflict</code></td><td>global hotkeys (conflict detection built in)</td></tr><tr><td>event</td><td><code>tui_event_register/unregister/list/dispatch</code></td><td>generic event subscribers</td></tr></tbody></table><p>Limits are named constants (<code>TUI_EXT_MENU_MAX</code>, ...) - bounded tables, refused loudly, never truncated.</p><h2 id="the-reference-implementations" tabindex="-1">The reference implementations <a class="header-anchor" href="#the-reference-implementations" aria-label="Permalink to &quot;The reference implementations&quot;">​</a></h2><p>The in-tree pages register exactly this way - <code>svc_tui_time.c</code> (<code>time.clock</code>, <code>time.tz</code>, <code>time.set</code>), <code>svc_tui_sys.c</code> (<code>sys.host</code>, ...), the hw/net/sysinfo/drv/sys families, and the desktop apps (<code>svc_tui_dt_*.c</code>). Read one before writing yours: register on init, unregister on teardown, owner-tagged.</p><h2 id="pages-vs-programs" tabindex="-1">Pages vs programs <a class="header-anchor" href="#pages-vs-programs" aria-label="Permalink to &quot;Pages vs programs&quot;">​</a></h2><p>The TUI renders the same services the merged apps wrap - the sysinfo pages read the same L1SVC ops <code>hwinfo</code> does. TUI pages are in-kernel service surfaces (through the registries above); the mega-apps are ring-3 programs; both doors lead to the same state.</p>',10)])])}const g=t(o,[["render",d]]);export{p as __pageData,g as default};
